package main

import (
	"encoding/json"
	"fmt"
	"math"
	"os"
)

type Data struct {
	Readings   []float64 `json:"readings"`
	Source     string    `json:"source"`
	Mean       float64   `json:"mean"`
	StdDev     float64   `json:"std_dev"`
	Min        float64   `json:"min"`
	Max        float64   `json:"max"`
	Anomalies  []float64 `json:"anomalies"`
}

func main() {
	fmt.Println("==========================================================")
	fmt.Println("📈 STEP 3: CALCULATING STATISTICS")
	fmt.Println("==========================================================")
	fmt.Println("")
	fmt.Println("💝 Pickup Line: Are you standard deviation? Because you're making my heart vary from the mean! 📊")
	fmt.Println("")

	// Read data
	fmt.Println("📖 Loading cleaned data...")
	file, _ := os.ReadFile("/shared/node_n2_output.json")
	var data Data
	json.Unmarshal(file, &data)
	fmt.Printf("📥 Loaded %d readings\n", len(data.Readings))

	// Calculate mean
	fmt.Println("🧮 Computing mean temperature...")
	sum := 0.0
	for _, r := range data.Readings {
		sum += r
	}
	data.Mean = sum / float64(len(data.Readings))
	fmt.Printf("   Mean: %.2f°C\n", data.Mean)

	// Calculate std dev, min, max
	fmt.Println("📐 Computing standard deviation...")
	variance := 0.0
	data.Min = data.Readings[0]
	data.Max = data.Readings[0]
	for _, r := range data.Readings {
		variance += (r - data.Mean) * (r - data.Mean)
		if r < data.Min {
			data.Min = r
		}
		if r > data.Max {
			data.Max = r
		}
	}
	data.StdDev = math.Sqrt(variance / float64(len(data.Readings)))
	fmt.Printf("   Std Dev: %.2f°C\n", data.StdDev)
	fmt.Printf("   Range: %.2f°C - %.2f°C\n", data.Min, data.Max)

	// Detect anomalies (>2 std from mean)
	fmt.Println("🔍 Detecting anomalies (>2σ from mean)...")
	for _, r := range data.Readings {
		if math.Abs(r-data.Mean) > 2*data.StdDev {
			data.Anomalies = append(data.Anomalies, r)
		}
	}

	if len(data.Anomalies) > 0 {
		fmt.Printf("⚠️  Found %d anomalie(s): %v\n", len(data.Anomalies), data.Anomalies)
	} else {
		fmt.Println("✅ No anomalies detected!")
	}

	// Save results
	output, _ := json.MarshalIndent(data, "", "  ")
	os.WriteFile("/shared/node_n3_output.json", output, 0644)

	fmt.Println("💾 Statistical analysis saved to /shared/node_n3_output.json")
	fmt.Println("✨ Step 3 complete!")
	fmt.Println("")
}

